from functools import total_ordering

@total_ordering
class Money:
    def __init__(self, paise, currency='INR'):
        self.paise = paise
        self.currency = currency

    @classmethod
    def from_rupees(cls, rupees):
        return cls(round(rupees * 100))

    def __add__(self, other):
        if self.currency != other.currency:
            raise ValueError('currency mismatch')
        return Money(self.paise + other.paise, self.currency)

    def __eq__(self, other):
        return (self.paise, self.currency) == (other.paise, other.currency)

    def __lt__(self, other):
        return self.paise < other.paise

    def __hash__(self):
        return hash((self.paise, self.currency))

    def __repr__(self):
        return f'Money({self.paise}, {self.currency!r})'

    def __str__(self):
        return f'Rs {self.paise / 100:.2f}'

price = Money.from_rupees(199.5) + Money(50)
print(price, repr(price), price > Money(100))
