import sys

class Account:
    kind = 'Basic'

    def __init__(self, owner):
        self.owner = owner
        self.balance = 0

    def available(self):
        return self.balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError('amount must be positive')
        self.balance += amount

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError('amount must be positive')
        if amount > self.available():
            raise ValueError('insufficient funds')
        self.balance -= amount

    def __str__(self):
        return f'{self.kind} {self.owner}: {self.balance}'

    def __lt__(self, other):
        return self.balance < other.balance

class SavingsAccount(Account):
    kind = 'Savings'
    MIN_BALANCE = 500

    def available(self):
        return self.balance - self.MIN_BALANCE

class CurrentAccount(Account):
    kind = 'Current'
    OVERDRAFT = 1000

    def available(self):
        return self.balance + self.OVERDRAFT

TYPES = {'savings': SavingsAccount, 'current': CurrentAccount}
accounts = {}

for line in sys.stdin:
    parts = line.split()
    if not parts:
        continue
    cmd = parts[0].upper()
    try:
        if cmd == 'OPEN':
            kind, owner = parts[1].lower(), parts[2]
            if owner in accounts:
                raise ValueError(f'account exists for {owner}')
            accounts[owner] = TYPES[kind](owner)
            print(f'Opened {accounts[owner].kind} account for {owner}')
        elif cmd in ('DEPOSIT', 'WITHDRAW'):
            owner, amount = parts[1], int(parts[2])
            acc = accounts.get(owner)
            if acc is None:
                raise ValueError(f'no account for {owner}')
            if cmd == 'DEPOSIT':
                acc.deposit(amount)
            else:
                acc.withdraw(amount)
            print(f'{owner} balance: {acc.balance}')
        elif cmd == 'REPORT':
            if not accounts:
                print('No accounts')
            for acc in sorted(accounts.values(), reverse=True):
                print(acc)
    except ValueError as exc:
        print(f'Error: {exc}')
